// weekDays labels the seven points of the area chart sample.
var weekDays = []string{"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}

// weekSeries pairs weekDays with values, one point per day.
func weekSeries(label string, values ...float64) areachart.Series {
	data := make([]areachart.DataPoint, len(values))
	for i, v := range values {
		data[i] = areachart.DataPoint{Label: weekDays[i%len(weekDays)], Value: v}
	}
	return areachart.Series{Label: label, Data: data}
}

